LoadingtextLocalData.tab = {
[10001] = {id = 10001, title = "Gigantification", text = "Gigantification\u{0020}is\u{0020}an\u{0020}avant-garde\u{0020}technology\u{0020}pioneered\u{0020}by\u{0020}Stephanix,\u{0020}which\u{0020}utilizes\u{0020}a\u{0020}specialized\u{0020}device\u{0020}to\u{0020}harness\u{0020}Nimbus\u{0020}Energy\u{0020}and\u{0020}enlarge\u{0020}a\u{0020}subject's\u{0020}body\u{0020}to\u{0020}approximately\u{0020}20\u{0020}times\u{0020}its\u{0020}original\u{0020}size.\u{0020}This\u{0020}process,\u{0020}a\u{0020}form\u{0020}of\u{0020}morph\u{0020}technology,\u{0020}employs\u{0020}Morph\u{0020}Cores\u{0020}to\u{0020}expand\u{0020}the\u{0020}subject's\u{0020}body\u{0020}composition,\u{0020}resulting\u{0020}in\u{0020}a\u{0020}massive\u{0020}increase\u{0020}in\u{0020}physical\u{0020}scale.", "巨大化", "史蒂芬妮利用尼姆比斯研发出的新技术，通过特殊的仪器，少女们的身体会被“放大”至20倍左右。当然，这其实也属于一种幻化，其增生的身体组织均是由特殊的幻化核心提供。"},
[10002] = {id = 10002, title = "Sin", text = "An\u{0020}extraterrestrial\u{0020}mechanical\u{0020}life\u{0020}form\u{0020}who\u{0020}descended\u{0020}upon\u{0020}Earth\u{0020}without\u{0020}warning,\u{0020}their\u{0020}arrival\u{0020}shrouded\u{0020}in\u{0020}mystery.\u{0020}These\u{0020}entities\u{0020}possess\u{0020}cores\u{0020}that\u{0020}bear\u{0020}a\u{0020}striking\u{0020}resemblance\u{0020}to\u{0020}the\u{0020}iridescent\u{0020}Prime\u{0020}Nimbus\u{0020}crystal\u{0020}discovered\u{0020}in\u{0020}the\u{0020}Korintia\u{0020}region.\u{0020}Among\u{0020}them,\u{0020}beings\u{0020}with\u{0020}a\u{0020}certain\u{0020}level\u{0020}of\u{0020}intelligence,\u{0020}known\u{0020}as\u{0020}Major\u{0020}Sins,\u{0020}are\u{0020}capable\u{0020}of\u{0020}generating\u{0020}Haze.\u{0020}These\u{0020}Major\u{0020}Sins\u{0020}possess\u{0020}the\u{0020}ability\u{0020}to\u{0020}evolve\u{0020}by\u{0020}devouring\u{0020}humans\u{0020}and\u{0020}artifacts\u{0020}alike,\u{0020}thus\u{0020}posing\u{0020}a\u{0020}profound\u{0020}threat\u{0020}to\u{0020}humanity.", "原罪", "突然降临到星球上的外星机器生命体，其核心与在卡佳地区发现的尼姆比斯结晶高度相似。它们似乎可以通过吞噬人类与人造物完成进化，对人类社会有较高的威胁性。其中具有一定智能且拥有制造苍雾能力的个体被称为高等原罪。"},
[10003] = {id = 10003, title = "Driver", text = "Those\u{0020}who\u{0020}possess\u{0020}the\u{0020}power\u{0020}to\u{0020}pilot\u{0020}AVGs\u{0020}are\u{0020}known\u{0020}as\u{0020}Sentinels.\u{0020}Anyone\u{0020}aspiring\u{0020}to\u{0020}become\u{0020}a\u{0020}Sentinel\u{0020}must\u{0020}first\u{0020}pass\u{0020}an\u{0020}aptitude\u{0020}test.\u{0020}Only\u{0020}those\u{0020}who\u{0020}succeed\u{0020}can\u{0020}proceed\u{0020}to\u{0020}learn\u{0020}the\u{0020}theoretical\u{0020}and\u{0020}practical\u{0020}knowledge\u{0020}required\u{0020}for\u{0020}combat.\u{0020}As\u{0020}a\u{0020}result,\u{0020}the\u{0020}current\u{0020}number\u{0020}of\u{0020}active\u{0020}Sentinels\u{0020}is\u{0020}relatively\u{0020}small.", "驾驶员", "拥有操作AVG能力的作战员均被称之为驾驶员（Driver）。想要成为驾驶员首先要进行的便是适格测试，通过测试的人才可以继续进行理论和实战知识的学习。现在在职的驾驶员的数量并不算特别多。"},
[10004] = {id = 10004, title = "Transformation\u{0020}Core", text = "Upon\u{0020}deciphering\u{0020}the\u{0020}mysteries\u{0020}of\u{0020}Nimbus,\u{0020}humanity\u{0020}harnessed\u{0020}warm-colored\u{0020}crystals\u{0020}derived\u{0020}from\u{0020}the\u{0020}Prime\u{0020}Nimbus\u{0020}to\u{0020}generate\u{0020}advanced\u{0020}armor.\u{0020}However,\u{0020}this\u{0020}armor\u{0020}requires\u{0020}a\u{0020}pilot\u{0020}to\u{0020}serve\u{0020}as\u{0020}its\u{0020}conscious\u{0020}medium,\u{0020}enabling\u{0020}control\u{0020}and\u{0020}operation.\u{0020}Morph\u{0020}Cores,\u{0020}the\u{0020}essential\u{0020}component\u{0020}of\u{0020}this\u{0020}technology,\u{0020}typically\u{0020}have\u{0020}a\u{0020}diameter\u{0020}of\u{0020}approximately\u{0020}10\u{0020}meters.", "幻化核心", "人类破译了尼姆比斯后，使用原初尼姆比斯制作出的暖色系晶体，拥有幻化出机甲的能力。但是幻化出的机甲必须要有作为“意识”载体的驾驶员操控。一般供驾驶员使用的幻化核心直径约为10m。"},
[10005] = {id = 10005, title = "Nimbus", text = "Nimbus\u{0020}forms\u{0020}The\u{0020}Sins'\u{0020}cores,\u{0020}manifesting\u{0020}as\u{0020}cold-colored\u{0020}crystals.\u{0020}It\u{0020}is\u{0020}akin\u{0020}to\u{0020}the\u{0020}stem\u{0020}cells\u{0020}of\u{0020}the\u{0020}universe,\u{0020}possessing\u{0020}the\u{0020}ability\u{0020}to\u{0020}alter\u{0020}various\u{0020}substances,\u{0020}energies,\u{0020}and\u{0020}even\u{0020}the\u{0020}fabric\u{0020}of\u{0020}time\u{0020}itself.\u{0020}This\u{0020}unique\u{0020}form\u{0020}is\u{0020}sustained\u{0020}by\u{0020}a\u{0020}code-like\u{0020}structure,\u{0020}similar\u{0020}to\u{0020}DNA,\u{0020}which\u{0020}humanity\u{0020}eventually\u{0020}deciphered\u{0020}in\u{0020}their\u{0020}quest\u{0020}to\u{0020}create\u{0020}Morph\u{0020}Cores.", "尼姆比斯", "原罪的核心，颜色为冷色系的晶体，尼姆比斯就像宇宙的干细胞，能变化成宇宙中的各种物质、能量甚至时间。维持其固有形态的是类似于人类DNA一样的代码，人类就是依靠破译这些代码来研究“幻化核心”。"},
}
return LoadingtextLocalData
